import{z as l,x as n,o as s,c as p,q as r,j as B,D as e,d as a,s as t,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"DoS 与放大","description":"","frontmatter":{"title":"DoS 与放大","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dos-amplify.md","filePath":"cs/dos-amplify.md","lastUpdated":1791413859000}'),d={name:"cs/dos-amplify.md"};function C(D,E,c,m,S,T){const o=n("Mermaid");return s(),p("div",null,[E[2]||(E[2]=r('<h1 id="dos-与放大" tabindex="-1">DoS 与放大 <a class="header-anchor" href="#dos-与放大" aria-label="Permalink to &quot;DoS 与放大&quot;">​</a></h1><div class="epigraph"><p>可用可以单独被打穿：请求不需要正确，只要贵；开放的应答器若把小询问变成大回答，攻击者可借别人的带宽。</p><footer>—— 据 Anderson 对拒绝服务；RFC 上对放大与 BCP38 源地址验证的讨论</footer></div><p><a href="/cs/hsts">上一课</a>处理主动假冒。本课不重做证书绑定。缺口是 CIA 的 <strong>A</strong>：服务可以密码学全对，仍因资源耗尽而停止。<a href="/cs/tcp-congestion">拥塞控制</a>管的是合作端点；敌手不合作，可以发洪水、耗连接表、或利用无连接协议的放大。本课只讲机制与防御原则，不给操作配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>防火墙状态表、2PC 的 prepared 锁、TLS 握手的公钥运算、都是有限资源。缺口不是「网络会慢」，而是敌手成本可以远低于受害者成本：伪造源地址使应答打向第三人；小查询大响应使带宽放大。TCP 三次握手已有半开连接这一课的对象；这里上升到安全：认证挡中间人，挡不住灌流量。</p><p><span class="marginnote">不描述如何寻找开放解析器、如何构造查询、如何选反射点。防御侧原则：源地址验证、限速、关闭开放应答、握手前便宜的 cookie。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缩小放大面：不向互联网提供开放的无认证应答；限制响应/请求比。入站：容量规划、任播、过滤显然伪造的源、SYN cookie 一类把状态推迟到证明对端。应用层：认证与配额，避免未认证的昂贵工作（与最小特权一致：先便宜检查）。本课不指定供应商产品。</p>',8)),(s(),B(i,null,{default:e(()=>[t(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E6%9C%89%E9%99%90%E8%B5%84%E6%BA%90%22%5D%20--%3E%20COST%5B%22%E6%95%8C%E6%89%8B%E4%BE%BF%E5%AE%9C%20%2F%20%E4%BD%A0%E8%B4%B5%22%5D%0A%20%20COST%20--%3E%20AMP%5B%22%E6%97%A0%E8%BF%9E%E6%8E%A5%E6%94%BE%E5%A4%A7%22%5D%0A%20%20COST%20--%3E%20STATE%5B%22%E7%8A%B6%E6%80%81%E8%A1%A8%E8%80%97%E5%B0%BD%22%5D%0A%20%20AMP%20--%3E%20END%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%AE%A1%E7%AE%97%E6%A0%88%E5%88%B0%E6%AD%A4%E4%B8%BA%E6%AD%A2%22%5D%0A%20%20STATE%20--%3E%20END%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("放大依赖「请求与响应路径分离」加「源可伪造」。BCP38 一类出口过滤从源头削弱伪造，是互联网集体行动，不是单机 TLS 能替代。应用层 DoS 可以全部是合法 TLS 请求，此时只能靠身份、配额与弹性。这把可用从「磁盘没坏」写成威胁模型里的一轴，与"),A("a",{href:"/cs/scheduling-metrics"},"调度指标"),a("的过载对照：那里假设工作负载诚实。")],-1)),(s(),B(i,null,{default:e(()=>[t(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20ATK%5B%22%E6%94%BB%E5%87%BB%E8%80%85%22%5D%20--%3E%7C%22%E5%B0%8F%E6%9F%A5%E8%AF%A2%EF%BC%8C%E4%BC%AA%E9%80%A0%E6%BA%90%E5%9C%B0%E5%9D%80%20%3D%20%E5%8F%97%E5%AE%B3%E8%80%85%20IP%22%7C%20RES%5B%22%E5%BC%80%E6%94%BE%E5%BA%94%E7%AD%94%E5%99%A8%22%5D%0A%20%20RES%20--%3E%7C%22%E5%A4%A7%E5%93%8D%E5%BA%94%E5%8F%91%E5%BE%80%E8%A2%AB%E5%86%92%E5%85%85%E7%9A%84%E5%9C%B0%E5%9D%80%22%7C%20VIC%5B%22%E5%8F%97%E5%AE%B3%E8%80%85%22%5D%0A%20%20ATK%20--%3E%20NET%5B%22%E4%BA%92%E8%81%94%E7%BD%91%22%5D%0A%20%20NET%20--%3E%7C%22%E5%87%BA%E5%8F%A3%E8%BF%87%E6%BB%A4%20BCP38%EF%BC%9A%E6%8B%A6%E6%88%AA%E4%BC%AA%E9%80%A0%E6%BA%90%22%7C%20RES%0A%20%20RES%20--%3E%7C%22%E9%99%90%E9%80%9F%20%2F%20%E5%85%B3%E9%97%AD%E5%BC%80%E6%94%BE%E5%BA%94%E7%AD%94%22%7C%20RES2%5B%22%E9%98%B2%E5%BE%A1%E7%82%B9%EF%BC%9A%E5%BA%94%E7%AD%94%E5%99%A8%E8%87%AA%E8%BA%AB%22%5D%0A%20%20VIC%20--%3E%7C%22%E6%8F%A1%E6%89%8B%E5%89%8D%E4%BE%BF%E5%AE%9C%20cookie%20%E6%8E%A8%E8%BF%9F%E7%8A%B6%E6%80%81%22%7C%20VIC2%5B%22%E9%98%B2%E5%BE%A1%E7%82%B9%EF%BC%9A%E5%8F%97%E5%AE%B3%E8%80%85%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">数字实例：一次几十字节的 DNS 查询可以换来数千字节的响应，放大几十倍——攻击者花 1 Gbps 的出口带宽喂给解析器，落到受害者头上的可能是 50 Gbps。这就是「敌手成本远低于受害者成本」的具体形状。</span></p><p><span class="marginnote">直觉类比：放大攻击像恶作剧者冒用你家的回邮地址，给一千家商店寄「缺货请补寄」的信——商家按地址把货全送到你家门口。商家没有做错什么，问题出在「寄信人地址没人验证」。</span></p><p>把昂贵公钥运算放在未证明对端之前，等于为洪水提供杠杆。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不覆盖物理切断、也不把勒索叙述写成教程。合法突发与攻击在包层面可以像，需要运维策略，不是一门新密码。下一课是本栏主干的最后一课：系统栈到此停，不再进入 Transformer 或限价簿。</p><p><span class="marginnote">常见误区：初学者容易以为「上了 TLS 就不怕 DoS」。实际上加密挡的是中间人（机密与完整），挡不住灌流量——洪水根本不需要被服务器「理解」，未认证阶段昂贵的公钥解密反而给攻击者提供了以小博大的杠杆。</span></p><p>应用层配额必须在认证之后仍按身份计，否则未登录的便宜路径会被用来耗尽后端。后课默认：CIA 三轴都已有机制名字；本栏不把大模型或盘口微观结构收进来。</p><p>容量与过滤挡的是资源不对称，不是身份。合法用户与敌手在未认证前可以长得一样，因此昂贵工作必须推迟到证明之后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>开放无认证应答器提供放大；源地址验证是集体防御，单机 TLS 替代不了。</p></li><li><p>下一课封口系统栈，不再把洪水写成新协议。</p></li><li><p>中间人伤 C/I；DoS 单独伤 A，可走洪水、状态、放大。</p></li><li><p>防御：少开放反射、源验证、推迟状态、配额。</p></li><li><p>主干在下一课封口并移交其他栏。</p></li><li><p>出处：Anderson, <em>Security Engineering</em>；关于源地址验证与放大的 IETF BCP 讨论。</p></li></ul>',10))])}const F=l(d,[["render",C]]);export{f as __pageData,F as default};
